"""Circuit faithfulness evaluation via node-level zero ablation."""

import re
from typing import Dict, Set, List, Any
from dataclasses import dataclass
from functools import partial

import torch


@dataclass
class CircuitEvalResult:
    name: str
    num_edges: int
    cpr: float
    cmd: float

    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "num_edges": self.num_edges,
            "cpr": round(self.cpr, 4),
            "cmd": round(self.cmd, 4),
        }


def _extract_circuit_nodes(circuit_edges: Set[str]) -> Set[str]:
    """Extract unique node names from edge set."""
    nodes = set()
    for edge in circuit_edges:
        parts = edge.split('->')
        if len(parts) != 2:
            continue
        src = parts[0].strip()
        dst = parts[1].strip()
        nodes.add(src)
        dst_base = re.sub(r'\.[qkv]$', '', dst)
        nodes.add(dst_base)
    nodes.discard('input')
    nodes.discard('logits')
    return nodes


def _parse_node(node_name: str):
    """Parse node name into (type, layer, head). Returns None if unparseable."""
    m = re.match(r'a(\d+)\.h(\d+)', node_name)
    if m:
        return ('attn', int(m.group(1)), int(m.group(2)))
    m = re.match(r'm(\d+)', node_name)
    if m:
        return ('mlp', int(m.group(1)), None)
    return None


def _head_ablation_hook(value, hook, heads_to_ablate):
    for h in heads_to_ablate:
        value[:, :, h, :] = 0
    return value


def _mlp_ablation_hook(value, hook):
    return torch.zeros_like(value)


def evaluate_circuit(model, circuit_edges: Set[str], clean_tokens, io_ids, s_ids) -> CircuitEvalResult:
    """Evaluate circuit faithfulness using node-level zero ablation."""
    if len(circuit_edges) == 0:
        return CircuitEvalResult(name="", num_edges=0, cpr=0.0, cmd=0.0)

    circuit_nodes = _extract_circuit_nodes(circuit_edges)
    n_layers = model.cfg.n_layers
    n_heads = model.cfg.n_heads

    ablate_heads_per_layer = {}
    ablate_mlp_layers = []

    for layer in range(n_layers):
        heads_to_ablate = []
        for head in range(n_heads):
            if f'a{layer}.h{head}' not in circuit_nodes:
                heads_to_ablate.append(head)
        if heads_to_ablate:
            ablate_heads_per_layer[layer] = heads_to_ablate
        if f'm{layer}' not in circuit_nodes:
            ablate_mlp_layers.append(layer)

    with torch.no_grad():
        baseline_logits = model(clean_tokens)
        baseline_diff = (
            baseline_logits[range(len(clean_tokens)), -1, io_ids] -
            baseline_logits[range(len(clean_tokens)), -1, s_ids]
        ).mean().item()

        hooks = []
        for layer, heads in ablate_heads_per_layer.items():
            hooks.append((
                f"blocks.{layer}.attn.hook_result",
                partial(_head_ablation_hook, heads_to_ablate=heads)
            ))
        for layer in ablate_mlp_layers:
            hooks.append((
                f"blocks.{layer}.hook_mlp_out",
                _mlp_ablation_hook
            ))

        circuit_logits = model.run_with_hooks(clean_tokens, fwd_hooks=hooks)
        circuit_diff = (
            circuit_logits[range(len(clean_tokens)), -1, io_ids] -
            circuit_logits[range(len(clean_tokens)), -1, s_ids]
        ).mean().item()

    cpr = circuit_diff / baseline_diff if abs(baseline_diff) > 1e-6 else 0.0
    cmd = abs(baseline_diff - circuit_diff)

    return CircuitEvalResult(name="", num_edges=len(circuit_edges), cpr=cpr, cmd=cmd)


def evaluate_all_circuits(model, circuits: Dict[str, Set[str]], clean_tokens, io_ids, s_ids) -> List[CircuitEvalResult]:
    results = []
    for name, edges in circuits.items():
        print(f"Evaluating circuit: {name} ({len(edges)} edges)")
        result = evaluate_circuit(model, edges, clean_tokens, io_ids, s_ids)
        result.name = name
        results.append(result)
    return results


def print_eval_table(results: List[CircuitEvalResult]) -> None:
    print(f"\n{'Circuit':<30} {'Edges':>6} {'CPR':>8} {'CMD':>8}")
    print("-" * 54)
    for r in sorted(results, key=lambda x: x.cpr, reverse=True):
        print(f"{r.name:<30} {r.num_edges:>6} {r.cpr:>8.4f} {r.cmd:>8.4f}")
    print()
